namespace {
bool subject_equal(const SubjectRef& a,const SubjectRef& c){return a.kind==c.kind&&a.id==c.id;}
void unique(const std::vector<StableId>& ids){std::set<StableId> found;for(const auto& id:ids)if(id.empty()||!found.insert(id).second)fail("DuplicateTransportMember",id);}
const TransportRegistrationSource& registration(const TransportRegistrationState& state,const SourceRef& ref){const auto* source=ref.domain=="travel"&&ref.kind=="transport_registration"?state.registrations.find(ref.id):nullptr;if(!source)fail("TransportRegistrationSourceRequired",ref.id);return *source;}
const TransportUnitReleaseSource& release(const TransportRegistrationState& state,const SourceRef& ref){const auto* source=ref.domain=="travel"&&ref.kind=="transport_release"?state.releases.find(ref.id):nullptr;if(!source)fail("TransportReleaseSourceRequired",ref.id);return *source;}
void true_fact(const CommonStore& common,const SourceRef& ref){const auto* fact=common.state().facts.find(ref.id);if(!fact||fact->domain!=ref.domain||fact->kind!=ref.kind)fail("TransportActualFactRequired",ref.id);}
const TransportSelectionRegistration& selected(const TransportRegistrationSource& source,const StableId& id){for(const auto& value:source.selections)if(value.selection_id==id)return value;fail("TransportSelectionNotAccepted",id);}
void same_site(std::optional<MovementAnchor>& accumulated,const MovementAnchor& next,ExactArithmeticBudget budget){if(accumulated){if(!take(same_spatial_anchor(*accumulated,next,budget)))fail("TransportMembersNotColocated");}else accumulated=next;}
SpatialCarrierRef ref_for(const TransportUnitState& unit){return TransportUnitCarrierRef{{unit.subject,unit.transport_unit_id},unit.composition_revision};}
void free_members(const CommonStore& common,const SpatialCarrierState& carriers,const TransportRegistrationAuthority& terms){unique(terms.named_participants);unique(terms.vehicle_refs);unique(terms.inventory_ids);unique(terms.accepted_selection_ids);for(const auto& id:terms.named_participants){const auto* actor=common.actor(id);if(!actor||!actor->alive||!actor->available||!actor->action_id.empty())fail("TransportParticipantBusy",id);if(std::holds_alternative<FollowingLocation>(actor->location)||std::holds_alternative<InArmyLocation>(actor->location)||std::holds_alternative<CarriedLocation>(actor->location))fail("TransportParticipantOriginalReleaseRequired",id);for(const auto& party:common.state().parties.rows())if(party.second.leader_id==id||std::find(party.second.members.begin(),party.second.members.end(),id)!=party.second.members.end())fail("TransportParticipantPartyReleaseRequired",id);}
for(const auto& row:carriers.transport_units.rows()){const auto& unit=row.second;if(unit.state==TransportUnitLifecycle::dissolved)continue;for(const auto& id:terms.named_participants)if(std::find(unit.named_participants.begin(),unit.named_participants.end(),id)!=unit.named_participants.end())fail("ActorInTwoTransportUnits",id);for(const auto& id:terms.vehicle_refs)if(std::find(unit.vehicle_refs.begin(),unit.vehicle_refs.end(),id)!=unit.vehicle_refs.end())fail("VehicleInTwoTransportUnits",id);for(const auto& id:terms.inventory_ids)if(std::find(unit.inventory_ids.begin(),unit.inventory_ids.end(),id)!=unit.inventory_ids.end())fail("InventoryInTwoTransportUnits",id);}}
}
Outcome<SubjectRef> read_registered_transport_subject(const CommonStore& common,const LocalEconomyState& economy,const PopulationTransportState& population,const TransportRegistrationSource& source){return guard<SubjectRef>([&]{
 const auto& accepted=source.accepted_scope;const SourceRef registration_ref{"travel","transport_registration",source.id};true_fact(common,registration_ref);
 if(!std::holds_alternative<HouseholdPolicyGroupInitiator>(accepted.initiator)||accepted.subject.kind!=SubjectKind::cohort)return accepted.subject;
 if(accepted.accepted_selection_ids.size()!=1||source.selections.size()!=1||source.selections.front().selection_id!=accepted.accepted_selection_ids.front())fail("HouseholdTransportSelectionScopeMismatch",source.id);
 const auto& id=accepted.accepted_selection_ids.front();const auto* selection=population.selections.find(id);const auto* result=population.materializations.find(id);
 if(!selection||!result||selection->id!=id||selection->state!=PopulationSelectionPhase::materialized||selection->purpose!=PopulationSelectionPurpose::household_purchase||selection->selected_persons!=1||selection->selected_labor_eligible!=1||selection->partition_policy!=PopulationPartitionPolicy::labor_eligible_only||selection->source.cohort_id!=accepted.subject.id||!same_source(selection->owner_business_ref,accepted.business_source)||result->selection_id!=id||result->source_cohort_ref.cohort_id!=selection->source.cohort_id||result->transfer_ref!=selection->result_transfer_ref||!result->result_cohort_ref.transport_binding_id)fail("HouseholdTransportMaterializedSubjectRequired",id);
 const auto* binding=population.transport_bindings.find(*result->result_cohort_ref.transport_binding_id);
 if(!binding||binding->binding_id!=*result->result_cohort_ref.transport_binding_id||binding->transport_cohort_id!=result->result_cohort_ref.cohort_id||binding->transport_unit_id!=source.transport_unit_id||!same_source(binding->registration_source_ref,registration_ref)||binding->source_population_transfer_ref!=result->transfer_ref||binding->created_tick!=source.occurred_at.half_day_tick||!same_source(result->location_binding_ref,{"travel","population_transport_position",binding->binding_id}))fail("HouseholdTransportMaterializedSubjectMismatch",id);
 if(result->transfer_ref){const auto* transfer=economy.population_transfers.find(*result->transfer_ref);if(!transfer||transfer->from_cohort_id!=selection->source.cohort_id||transfer->to_cohort_id!=binding->transport_cohort_id||transfer->source_fact_id!=source.id)fail("HouseholdTransportOriginalSplitRequired",id);}else if(binding->transport_cohort_id!=selection->source.cohort_id)fail("HouseholdTransportOriginalSplitRequired",id);
 const auto historical=take(read_population_revision_source(economy,population,result->result_cohort_ref));if(historical.headcount!=1||historical.labor_capacity!=1||!same_source(historical.location_binding_ref,result->location_binding_ref))fail("HouseholdTransportMaterializedCountMismatch",id);
 return SubjectRef{SubjectKind::cohort,binding->transport_cohort_id};
});}
NativePopulationTransportSources::NativePopulationTransportSources(const CommonStore& common,const LocalEconomyState& economy,const PopulationTransportState& population,const SpatialCarrierState& carriers,const TransportRegistrationState& registrations,const PopulationTransportSourceRead& selections,const TransportRegistrationBusinessRead& business):common_(common),economy_(economy),population_(population),carriers_(carriers),registrations_(registrations),selection_sources_(selections),business_(business){}
Outcome<PopulationSelectionAuthority> NativePopulationTransportSources::read_population_selection_authority(const PopulationSelectionRequest& request)const{return selection_sources_.read_population_selection_authority(request);}
Status NativePopulationTransportSources::validate_population_selection_release(const PopulationSelection& selection,const SourceRef& source)const{return selection_sources_.validate_population_selection_release(selection,source);}
Outcome<PopulationMaterializationSource> NativePopulationTransportSources::read_population_transport_registration(const RegisterPopulationTransportFromSelection& request)const{return guard<PopulationMaterializationSource>([&]{const auto& source=registration(registrations_,request.transport_registration_source_ref);true_fact(common_,request.transport_registration_source_ref);take(business_.validate_registration_authority(source.accepted_scope));const auto& pick=selected(source,request.accepted_selection_id);if(source.transport_unit_id!=request.transport_unit_id||source.accepted_scope.accepted_scope_revision!=request.accepted_scope_revision||!same_source(source.accepted_scope.business_source,request.accepting_business_ref)||!same_source(pick.departure_anchor_ref,request.departure_anchor_ref))fail("TransportRegistrationAcceptanceMismatch",source.id);return PopulationMaterializationSource{request.transport_registration_source_ref,pick.selection_id,source.transport_unit_id,pick.departure_anchor_ref,source.occurred_at.half_day_tick,source.accepted_scope.accepted_scope_revision,source.accepted_scope.labor_until_tick,pick.release_allocation_ids,source.occurred_at};});}
Status NativePopulationTransportSources::validate_population_transport_binding(const PopulationTransportBinding& binding)const{return status([&]{const auto& source=registration(registrations_,binding.registration_source_ref);true_fact(common_,binding.registration_source_ref);const auto* unit=carriers_.transport_units.find(binding.transport_unit_id);if(!unit||source.transport_unit_id!=unit->transport_unit_id||!same_source(unit->registration_source_ref,binding.registration_source_ref))fail("TransportPopulationBacklinkMismatch",binding.binding_id);bool linked=false;for(const auto& pick:source.selections){const auto* result=population_.materializations.find(pick.selection_id);if(result&&result->result_cohort_ref.transport_binding_id==std::optional<StableId>{binding.binding_id}&&result->result_cohort_ref.cohort_id==binding.transport_cohort_id)linked=true;}if(!linked)fail("TransportPopulationMaterializationRequired",binding.binding_id);if(binding.state!=PopulationTransportPhase::released){if(unit->state==TransportUnitLifecycle::dissolved)fail("DissolvedTransportHasPopulation",unit->transport_unit_id);const SourceRef own{"local_economy","population_transport_binding",binding.binding_id};if(std::none_of(unit->population_binding_refs.begin(),unit->population_binding_refs.end(),[&](const auto& r){return same_source(r,own);}))fail("TransportPopulationBacklinkMismatch",binding.binding_id);}for(const auto& id:binding.labor_allocation_refs){const auto* allocation=economy_.labor_allocations.find(id);if(!allocation||allocation->cohort_id!=binding.transport_cohort_id||allocation->activity_or_production_id!=unit->transport_unit_id||allocation->commitment_id!=source.id)fail("TransportLaborBacklinkMismatch",id);}});}
Status NativePopulationTransportSources::validate_population_transport_release(const PopulationTransportBinding& binding,const SourceRef& ref)const{return status([&]{const auto& source=release(registrations_,ref);true_fact(common_,ref);const auto* unit=carriers_.transport_units.find(binding.transport_unit_id);if(!unit||source.transport_unit_id!=binding.transport_unit_id||std::find(source.population_binding_ids.begin(),source.population_binding_ids.end(),binding.binding_id)==source.population_binding_ids.end())fail("TransportPopulationReleaseMismatch",binding.binding_id);take(business_.validate_transport_handover(source,source.released_composition));});}
Outcome<PopulationTransportReleaseSource> NativePopulationTransportSources::read_population_transport_release(const PopulationTransportBinding& binding,const SourceRef& ref)const{return guard<PopulationTransportReleaseSource>([&]{take(validate_population_transport_release(binding,ref));const auto& source=release(registrations_,ref);return PopulationTransportReleaseSource{ref,source.handover_site_id,source.occurred_at.half_day_tick,ref,source.occurred_at};});}
Outcome<std::optional<TransportUnitRef>> read_actor_transport_participation(const SpatialCarrierState& carriers,const StableId& actor){return guard<std::optional<TransportUnitRef>>([&]{std::optional<TransportUnitRef> out;for(const auto& row:carriers.transport_units.rows()){const auto& unit=row.second;if(unit.state==TransportUnitLifecycle::dissolved||std::find(unit.named_participants.begin(),unit.named_participants.end(),actor)==unit.named_participants.end())continue;if(out)fail("ActorInTwoTransportUnits",actor);out=TransportUnitRef{unit.subject,unit.transport_unit_id};}return out;});}
Outcome<MovementAnchor> read_population_transport_anchor(const LocalEconomyState& economy,const PopulationTransportState& population,const SpatialCarrierState& carriers,const MovementExactState& movement,const StableId& binding_id,ExactArithmeticBudget budget){return guard<MovementAnchor>([&]{auto binding=take(read_population_transport_binding(economy,population,binding_id));const auto* unit=carriers.transport_units.find(binding.transport_unit_id);if(!unit||unit->state==TransportUnitLifecycle::dissolved||binding.state==PopulationTransportPhase::released)fail("PopulationTransportNotActive",binding_id);return take(read_carrier_movement_anchor(movement,ref_for(*unit),budget));});}
