Status validate_transport_registration_sources(const CommonStore& common,const LocalEconomyState& economy,const PopulationTransportState& population,const SpatialCarrierState& carriers,const MovementExactState& movement,const TransportRegistrationState& registrations,const PopulationTransportSourceRead& selections,const TransportRegistrationBusinessRead& business,const TransportVehicleTakeover& vehicles,ExactArithmeticBudget budget){return status([&]{NativePopulationTransportSources population_sources(common,economy,population,carriers,registrations,selections,business);for(const auto& row:registrations.registrations.rows()){const auto& source=row.second;const auto* unit=carriers.transport_units.find(source.transport_unit_id);if(row.first!=source.id||!unit||!same_source(unit->registration_source_ref,{"travel","transport_registration",source.id})||!subject_equal(unit->subject,take(read_registered_transport_subject(common,economy,population,source)))||source.actual_vehicle_takeover_refs.size()!=source.accepted_scope.vehicle_refs.size())fail("TransportRegistrationSourceMismatch",row.first);true_fact(common,{"travel","transport_registration",source.id});take(business.validate_registration_authority(source.accepted_scope));take(encode_world_moment(source.occurred_at,budget));for(std::size_t i=0;i<source.actual_vehicle_takeover_refs.size();++i)take(vehicles.validate_vehicle_takeover(source.actual_vehicle_takeover_refs[i],source.accepted_scope.vehicle_refs[i],{unit->subject,unit->transport_unit_id}));for(const auto& pick:source.selections){const auto* result=population.materializations.find(pick.selection_id);if(!result||!result->result_cohort_ref.transport_binding_id)fail("TransportPopulationMaterializationRequired",pick.selection_id);const auto* binding=population.transport_bindings.find(*result->result_cohort_ref.transport_binding_id);if(!binding)fail("TransportPopulationBindingRequired",pick.selection_id);take(population_sources.validate_population_transport_binding(*binding));}if(unit->state!=TransportUnitLifecycle::dissolved)take(read_carrier_movement_anchor(movement,ref_for(*unit),budget));}
for(const auto& row:registrations.releases.rows()){const auto& source=row.second;const auto* unit=carriers.transport_units.find(source.transport_unit_id);if(row.first!=source.id||!unit||unit->state!=TransportUnitLifecycle::dissolved||unit->composition_revision!=source.composition_revision+1)fail("TransportReleaseSourceMismatch",row.first);true_fact(common,{"travel","transport_release",source.id});take(business.validate_transport_handover(source,source.released_composition));for(const auto& id:source.population_binding_ids){const auto* binding=population.transport_bindings.find(id);if(!binding||binding->state!=PopulationTransportPhase::released)fail("TransportPopulationReleaseRequired",id);take(population_sources.validate_population_transport_release(*binding,{"travel","transport_release",source.id}));}}});}
